    "login.tunnel_confirm_extra": "\n🌐 Away from this machine? \"Temporary public link\" puts this same terminal on a temporary PUBLIC https link (a Cloudflare tunnel — the traffic, including what you type, passes through Cloudflare). ⚠️ Until this login ends, anyone who has the link and its access token can use this login terminal. Both are sent to you privately, as two messages — never in this channel — and the link closes when the login ends. If cloudflared is not installed, AgEnD first downloads Cloudflare's official build (pinned version, SHA256-checked) into its own folder — no sudo. \"Local network\" keeps everything on this machine.",
