    "fleet.kiro_incompat_general": "[system:kiro-incompat] 已安裝的 kiro-cli 無法照設定執行這些 kiro Agent，所以 AgEnD 已停下它們，不會自動重試：{0}。\n原因：{1}\n使用者已經在 fleet 的 General 主題看到這則通知。它們的對話都還在 —— 沒有任何東西被轉換或刪除。請載入 kiro-engine-migration skill，並呼叫 kiro_engine_status 看每個 Agent 的引擎、版本以及卡住的原因，以便在使用者詢問時說明狀況與可行選項。不要回覆這則訊息，也不要自行啟動、重啟或遷移任何 Agent。",
    "inst.mcp_never_connected_auto": "⚠️ `{0}` 的 CLI 在執行，但 AgEnD 的 MCP 伺服器一直沒有連上 —— 這個 Agent 目前沒有 agend 工具（無法 reply / 跨 Agent 通訊）。等它閒置後會自動重啟再試一次（工作階段會保留）。若重複發生，請看它窗格裡 CLI 的 MCP 啟動訊息。",
