    "login.token_pasted": "🔒 這是 {0} 登入的一次性存取 token —— 請不要貼到聊天裡：這裡的每個人和 agent 都看得到。我已把它遮掉、作廢，並私訊你一個新的。新的 token 請貼到終端頁面：用瀏覽器打開「🔐 {0} 登入」那則訊息裡的終端連結，頁面會要你輸入 token。",
    "login.token_pasted_web": "🔒 這是 {0} 登入的一次性存取 token —— 請不要貼到聊天裡：這裡的每個人和 agent 都看得到。我已把它遮掉並作廢；儀表板上的登入視窗會顯示新的 token，請貼到它打開的終端頁面。",
