    "login.tunnel_confirm_extra": "\n🌐 人不在這台機器旁？「外網臨時連結」會為同一條終端開一個臨時的公開 https 連結（Cloudflare 通道 —— 流量，包括你輸入的內容，會經過 Cloudflare）。⚠️ 在這次登入結束前，任何拿到連結和存取 token 的人都能使用這個登入終端。兩者都只會分成兩則私訊給你、絕不貼在這個頻道，登入結束連結就關閉。若尚未安裝 cloudflared，AgEnD 會先把 Cloudflare 官方版本（固定版本、比對 SHA256）下載到 AgEnD 自己的資料夾——不需要 sudo。「內網」則一切都留在這台機器上。",
